const cfg = $('Configuration').first().json;
const today = DateTime.now().setZone('Europe/Paris').startOf('day');
function d(x) { return x.toFormat('yyyy-MM-dd'); }
const end = today.minus({ days: 1 });
const start = end.minus({ days: 6 });
const prevEnd = start.minus({ days: 1 });
const prevStart = prevEnd.minus({ days: 6 });
const lag = Math.max(2, Number(cfg.gsc_lag_days) || 3);
const gEnd = today.minus({ days: lag });
const gStart = gEnd.minus({ days: 6 });
const gPrevEnd = gStart.minus({ days: 1 });
const gPrevStart = gPrevEnd.minus({ days: 6 });
const ranges = [
  { startDate: d(start), endDate: d(end), name: 'current' },
  { startDate: d(prevStart), endDate: d(prevEnd), name: 'previous' }
];
return [{ json: {
  run_id: $execution.id + '-' + today.toFormat('yyyyLLdd'),
  current_start: d(start), current_end: d(end),
  previous_start: d(prevStart), previous_end: d(prevEnd),
  gsc_current_start: d(gStart), gsc_current_end: d(gEnd),
  gsc_previous_start: d(gPrevStart), gsc_previous_end: d(gPrevEnd),
  ga4_property_id: String(cfg.ga4_property_id || '').split('properties/').join('').trim(),
  gsc_site_path: encodeURIComponent(String(cfg.gsc_property || '').trim()),
  ga4_traffic_body: { dateRanges: ranges, metrics: [{ name: 'sessions' }, { name: 'totalUsers' }, { name: 'engagedSessions' }, { name: 'keyEvents' }] },
  ga4_channels_body: { dateRanges: ranges, dimensions: [{ name: 'sessionDefaultChannelGroup' }], metrics: [{ name: 'sessions' }, { name: 'keyEvents' }], limit: 50 },
  gsc_totals_body: { startDate: d(gPrevStart), endDate: d(gEnd), dimensions: ['date'], type: 'web', rowLimit: 100 },
  gsc_queries_body: { startDate: d(gStart), endDate: d(gEnd), dimensions: ['query'], type: 'web', rowLimit: 250 },
  gsc_queries_prev_body: { startDate: d(gPrevStart), endDate: d(gPrevEnd), dimensions: ['query'], type: 'web', rowLimit: 250 }
} }];

const p = $('Calculer les périodes').first().json;
const cfg = $('Configuration').first().json;

function safeAll(name) {
  try { return $(name).all().map(function (i) { return i.json; }); } catch (e) { return null; }
}
function errorOf(items) {
  if (items === null) return 'Étape non exécutée';
  const j = items[0] || {};
  if (!j.error) return '';
  if (typeof j.error === 'string') return j.error.slice(0, 300);
  return String(j.error.message || j.error.description || JSON.stringify(j.error)).slice(0, 300);
}
function num(v) { const n = Number(v); return isFinite(n) ? n : 0; }
function round(n, dec) { const f = Math.pow(10, dec); return Math.round(n * f) / f; }
function change(cur, prev) {
  if (cur === null || cur === undefined || !prev) return null;
  return round(((cur - prev) / prev) * 100, 1);
}
function ga4ByRange(resp) {
  const out = {};
  if (!resp || !resp.metricHeaders) return out;
  const mh = resp.metricHeaders.map(function (h) { return h.name; });
  const dh = (resp.dimensionHeaders || []).map(function (h) { return h.name; });
  const di = dh.indexOf('dateRange');
  (resp.rows || []).forEach(function (r) {
    const dims = (r.dimensionValues || []).map(function (x) { return x.value; });
    const range = di >= 0 ? dims[di] : 'current';
    const key = dims.filter(function (v, k) { return k !== di; }).join(' | ');
    const m = {};
    mh.forEach(function (h, k) { m[h] = num((r.metricValues[k] || {}).value); });
    if (!out[range]) out[range] = [];
    out[range].push({ key: key, m: m });
  });
  return out;
}
function gscAgg(rows, from, to) {
  let clicks = 0, impressions = 0, posWeighted = 0;
  rows.forEach(function (r) {
    const day = r.keys[0];
    if (day >= from && day <= to) {
      clicks += num(r.clicks);
      impressions += num(r.impressions);
      posWeighted += num(r.position) * num(r.impressions);
    }
  });
  return { clicks: clicks, impressions: impressions, ctr: impressions ? round(clicks / impressions * 100, 2) : null, position: impressions ? round(posWeighted / impressions, 1) : null };
}
function queryMap(items) {
  if (!items || errorOf(items)) return null;
  const m = {};
  ((items[0] && items[0].rows) || []).forEach(function (r) {
    m[r.keys[0]] = { clicks: num(r.clicks), impressions: num(r.impressions), position: round(num(r.position), 1) };
  });
  return m;
}
function sumAds(items) {
  let cost = 0, inter = 0, impr = 0;
  const camps = [];
  items.forEach(function (c) {
    if (!c || (c.costMicros === undefined && c.impressions === undefined)) return;
    const co = num(c.costMicros) / 1000000;
    if (!co && !num(c.impressions)) return;
    cost += co; inter += num(c.interactions); impr += num(c.impressions);
    camps.push({ campagne: c.name, statut: c.status, cout: round(co, 2), interactions: num(c.interactions) });
  });
  return { cost: round(cost, 2), interactions: inter, impressions: impr, camps: camps };
}

const unavailable = [];

let ga4 = { status: 'ok' };
const gaTraffic = safeAll('GA4 : trafic sur deux semaines');
const gaErr = errorOf(gaTraffic);
if (gaErr) {
  ga4 = { status: 'erreur', error: gaErr };
  unavailable.push({ source: 'GA4', error: gaErr });
} else {
  const r = ga4ByRange(gaTraffic[0]);
  const cur = ((r.current || [])[0] || { m: {} }).m;
  const prev = ((r.previous || [])[0] || { m: {} }).m;
  ga4.sessions = num(cur.sessions); ga4.sessions_prev = num(prev.sessions);
  ga4.sessions_change = change(ga4.sessions, ga4.sessions_prev);
  ga4.users = num(cur.totalUsers); ga4.users_prev = num(prev.totalUsers);
  ga4.users_change = change(ga4.users, ga4.users_prev);
  ga4.engagement_rate = ga4.sessions ? round(num(cur.engagedSessions) / ga4.sessions * 100, 1) : null;
  ga4.engagement_rate_prev = ga4.sessions_prev ? round(num(prev.engagedSessions) / ga4.sessions_prev * 100, 1) : null;
  ga4.key_events = num(cur.keyEvents); ga4.key_events_prev = num(prev.keyEvents);
  ga4.key_events_change = change(ga4.key_events, ga4.key_events_prev);
  const gaChannels = safeAll('GA4 : canaux');
  const chErr = errorOf(gaChannels);
  if (chErr) {
    ga4.channels_error = chErr;
  } else {
    const rc = ga4ByRange(gaChannels[0]);
    const prevMap = {};
    (rc.previous || []).forEach(function (x) { prevMap[x.key] = x.m.sessions; });
    ga4.canaux = (rc.current || []).map(function (x) {
      return { canal: x.key, sessions: x.m.sessions, sessions_prev: num(prevMap[x.key]), variation: change(x.m.sessions, num(prevMap[x.key])), conversions_cles: x.m.keyEvents };
    }).sort(function (a, b) { return b.sessions - a.sessions; }).slice(0, 8);
  }
}

let gsc = { status: 'ok', fenetre: p.gsc_current_start + ' au ' + p.gsc_current_end };
const gscTotals = safeAll('Search Console : totaux');
const gscErr = errorOf(gscTotals);
if (gscErr) {
  gsc = { status: 'erreur', error: gscErr };
  unavailable.push({ source: 'Search Console', error: gscErr });
} else {
  const rows = (gscTotals[0] && gscTotals[0].rows) || [];
  const cur = gscAgg(rows, p.gsc_current_start, p.gsc_current_end);
  const prev = gscAgg(rows, p.gsc_previous_start, p.gsc_previous_end);
  gsc.clicks = cur.clicks; gsc.clicks_prev = prev.clicks; gsc.clicks_change = change(cur.clicks, prev.clicks);
  gsc.impressions = cur.impressions; gsc.impressions_prev = prev.impressions; gsc.impressions_change = change(cur.impressions, prev.impressions);
  gsc.ctr = cur.ctr; gsc.ctr_prev = prev.ctr;
  gsc.position = cur.position; gsc.position_prev = prev.position;
  const qc = queryMap(safeAll('Search Console : requêtes'));
  const qp = queryMap(safeAll('Search Console : requêtes semaine précédente'));
  if (qc) {
    gsc.top_requetes = Object.keys(qc).map(function (q) {
      return { requete: q, clics: qc[q].clicks, impressions: qc[q].impressions, position: qc[q].position, clics_prev: qp && qp[q] ? qp[q].clicks : null };
    }).sort(function (a, b) { return b.clics - a.clics || b.impressions - a.impressions; }).slice(0, 10);
  }
  if (qc && qp) {
    const all = {};
    Object.keys(qc).forEach(function (q) { all[q] = true; });
    Object.keys(qp).forEach(function (q) { all[q] = true; });
    const deltas = Object.keys(all).map(function (q) {
      const c = qc[q] ? qc[q].clicks : 0;
      const pv = qp[q] ? qp[q].clicks : 0;
      return { requete: q, clics: c, clics_prev: pv, ecart: c - pv, position: qc[q] ? qc[q].position : null, position_prev: qp[q] ? qp[q].position : null };
    });
    gsc.gagnantes = deltas.filter(function (x) { return x.ecart > 0; }).sort(function (a, b) { return b.ecart - a.ecart; }).slice(0, 5);
    gsc.perdantes = deltas.filter(function (x) { return x.ecart < 0; }).sort(function (a, b) { return a.ecart - b.ecart; }).slice(0, 5);
  }
}

let ads = { status: 'non utilisé' };
if (cfg.google_ads_active) {
  const a7 = safeAll('Google Ads : 7 jours');
  const a14 = safeAll('Google Ads : 14 jours');
  const adsErr = errorOf(a7) || errorOf(a14);
  if (adsErr) {
    ads = { status: 'erreur', error: adsErr };
    unavailable.push({ source: 'Google Ads', error: adsErr });
  } else {
    const s7 = sumAds(a7);
    const s14 = sumAds(a14);
    ads = {
      status: 'ok',
      cost: s7.cost, cost_prev: round(s14.cost - s7.cost, 2), cost_change: change(s7.cost, round(s14.cost - s7.cost, 2)),
      interactions: s7.interactions, interactions_prev: s14.interactions - s7.interactions,
      interactions_change: change(s7.interactions, s14.interactions - s7.interactions),
      campagnes: s7.camps.sort(function (a, b) { return b.cout - a.cout; }).slice(0, 5)
    };
  }
}

const history = (safeAll('Lire les semaines précédentes') || []).filter(function (h) { return h && h.period_end; }).map(function (h) {
  return { semaine_du: String(h.period_start).slice(0, 10), sessions: h.sessions, clics_search_console: h.gsc_clicks, depense_ads: h.ads_cost };
});

const hasData = ga4.status === 'ok' || gsc.status === 'ok' || ads.status === 'ok';

return [{ json: {
  run_id: p.run_id,
  current_start: p.current_start, current_end: p.current_end,
  gsc_current_start: p.gsc_current_start, gsc_current_end: p.gsc_current_end,
  has_data: hasData,
  errors_html: unavailable.map(function (u) { return '<li><strong>' + u.source + '</strong> : ' + String(u.error).split('<').join('&lt;') + '</li>'; }).join(''),
  facts: {
    site: cfg.site_name,
    semaine: p.current_start + ' au ' + p.current_end,
    semaine_precedente: p.previous_start + ' au ' + p.previous_end,
    ga4: ga4,
    search_console: gsc,
    google_ads: ads,
    historique: history,
    sources_indisponibles: unavailable
  }
} }];

const a = $('Assembler les indicateurs').first().json;
const cfg = $('Configuration').first().json;
const raw = $input.first().json;
const f = a.facts;
const g = f.ga4 || {};
const s = f.search_console || {};
const ads = f.google_ads || {};

const TD = 'padding:8px 12px;border-top:1px solid #e6e8ec;text-align:right;';
const TDL = 'padding:8px 12px;border-top:1px solid #e6e8ec;';
const MUTED = '#5b6472';

function esc(v) { return String(v === null || v === undefined ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function clean(v) {
  const em = String.fromCharCode(8212), en = String.fromCharCode(8211);
  return String(v || '').split(' ' + em + ' ').join(', ').split(' ' + en + ' ').join(', ').split(em).join(', ').split(en).join('-');
}
function fmt(v, dec) {
  if (v === null || v === undefined || v === '' || isNaN(Number(v))) return 'n.d.';
  return Number(v).toLocaleString('fr-FR', { maximumFractionDigits: dec || 0 });
}
function day(iso) { return DateTime.fromISO(iso).setLocale('fr').toFormat('d LLL'); }
function tone(delta, lowerIsBetter, neutral) {
  if (delta === null || delta === undefined || delta === 0 || neutral) return MUTED;
  return (lowerIsBetter ? delta < 0 : delta > 0) ? '#1a7f4b' : '#b42318';
}
function pctCell(delta, neutral) {
  if (delta === null || delta === undefined) return '<td style="' + TD + 'color:' + MUTED + '">n.d.</td>';
  return '<td style="' + TD + 'font-weight:600;color:' + tone(delta, false, neutral) + '">' + (delta > 0 ? '+' : '') + fmt(delta, 1) + ' %</td>';
}
function diffCell(cur, prev, unit, lowerIsBetter) {
  if (cur === null || cur === undefined || prev === null || prev === undefined) return '<td style="' + TD + 'color:' + MUTED + '">n.d.</td>';
  const delta = Math.round((cur - prev) * 10) / 10;
  return '<td style="' + TD + 'font-weight:600;color:' + tone(delta, lowerIsBetter) + '">' + (delta > 0 ? '+' : '') + fmt(delta, 1) + ' ' + unit + '</td>';
}
function line(label, cur, prev, cell) {
  return '<tr><td style="' + TDL + '">' + esc(label) + '</td><td style="' + TD + 'font-weight:600">' + cur + '</td><td style="' + TD + 'color:' + MUTED + '">' + prev + '</td>' + cell + '</tr>';
}
function section(label) {
  return '<tr><td colspan="4" style="padding:18px 12px 6px;font-size:12px;letter-spacing:.04em;text-transform:uppercase;color:' + MUTED + ';font-weight:700">' + esc(label) + '</td></tr>';
}
function bullets(title, list) {
  if (!Array.isArray(list) || !list.length) return '';
  return '<h3 style="font-size:15px;margin:18px 0 6px">' + esc(title) + '</h3><ul style="margin:0;padding-left:20px;line-height:1.55">' + list.map(function (x) { return '<li>' + esc(clean(x)) + '</li>'; }).join('') + '</ul>';
}
function queryTable(title, list) {
  if (!Array.isArray(list) || !list.length) return '';
  let h = '<h3 style="font-size:15px;margin:24px 0 8px">' + esc(title) + '</h3><table style="width:100%;border-collapse:collapse;font-size:14px">';
  h += '<tr style="color:' + MUTED + ';font-size:12px"><td style="padding:6px 12px">Requête</td><td style="padding:6px 12px;text-align:right">Clics</td><td style="padding:6px 12px;text-align:right">Avant</td><td style="padding:6px 12px;text-align:right">Position</td></tr>';
  list.forEach(function (q) {
    h += '<tr><td style="' + TDL + '">' + esc(q.requete) + '</td><td style="' + TD + 'font-weight:600">' + fmt(q.clics) + '</td><td style="' + TD + 'color:' + MUTED + '">' + fmt(q.clics_prev) + '</td><td style="' + TD + '">' + fmt(q.position, 1) + '</td></tr>';
  });
  return h + '</table>';
}
function claudeText(r) {
  if (!r || !Array.isArray(r.content)) return '';
  return r.content.filter(function (b) { return b && b.type === 'text'; }).map(function (b) { return b.text || ''; }).join('');
}
function claudeError(r) {
  if (!r || typeof r !== 'object') return 'aucune réponse';
  if (typeof r.error === 'string') return r.error;
  if (r.error && r.error.message) return String(r.error.message);
  if (r.stop_reason === 'refusal') return 'refus du modèle';
  if (r.stop_reason === 'max_tokens') return 'réponse coupée';
  return '';
}
function parseJson(t) {
  const i = t.indexOf('{'), j = t.lastIndexOf('}');
  if (i < 0 || j <= i) return null;
  try { return JSON.parse(t.slice(i, j + 1)); } catch (e) { return null; }
}

const text = claudeText(raw);
const parsed = text ? parseJson(text) : null;
let synth = '';
if (parsed) {
  synth = '<p style="font-size:17px;font-weight:600;margin:0 0 8px">' + esc(clean(parsed.titre)) + '</p>' +
    bullets('Ce qui a bougé', parsed.faits) + bullets('Points de vigilance', parsed.alertes) + bullets('À faire cette semaine', parsed.actions);
} else if (text) {
  synth = '<p style="white-space:pre-wrap;line-height:1.55">' + esc(clean(text)) + '</p>';
} else {
  synth = '<p style="padding:12px 14px;background:#fdecea;border-radius:6px">Synthèse IA indisponible (' + esc(claudeError(raw) || 'réponse vide') + '). Les chiffres ci-dessous restent fiables.</p>';
}

let rows = '';
if (g.status === 'ok') {
  rows += section('Trafic du site, GA4');
  rows += line('Sessions', fmt(g.sessions), fmt(g.sessions_prev), pctCell(g.sessions_change));
  rows += line('Utilisateurs', fmt(g.users), fmt(g.users_prev), pctCell(g.users_change));
  rows += line("Taux d'engagement", fmt(g.engagement_rate, 1) + ' %', fmt(g.engagement_rate_prev, 1) + ' %', diffCell(g.engagement_rate, g.engagement_rate_prev, 'pt', false));
  rows += line('Conversions clés', fmt(g.key_events), fmt(g.key_events_prev), pctCell(g.key_events_change));
}
if (s.status === 'ok') {
  rows += section('Recherche Google, Search Console du ' + day(a.gsc_current_start) + ' au ' + day(a.gsc_current_end));
  rows += line('Clics', fmt(s.clicks), fmt(s.clicks_prev), pctCell(s.clicks_change));
  rows += line('Impressions', fmt(s.impressions), fmt(s.impressions_prev), pctCell(s.impressions_change));
  rows += line('CTR', fmt(s.ctr, 2) + ' %', fmt(s.ctr_prev, 2) + ' %', diffCell(s.ctr, s.ctr_prev, 'pt', false));
  rows += line('Position moyenne', fmt(s.position, 1), fmt(s.position_prev, 1), diffCell(s.position, s.position_prev, 'place', true));
}
if (ads.status === 'ok') {
  rows += section('Google Ads');
  rows += line('Dépense (devise du compte)', fmt(ads.cost, 2), fmt(ads.cost_prev, 2), pctCell(ads.cost_change, true));
  rows += line('Interactions', fmt(ads.interactions), fmt(ads.interactions_prev), pctCell(ads.interactions_change));
}

let missing = '';
if (f.sources_indisponibles.length) {
  missing = '<div style="margin-top:20px;padding:12px 14px;background:#fff4e5;border-radius:6px;font-size:13px;line-height:1.5"><strong>Sources indisponibles cette semaine</strong><br>' +
    f.sources_indisponibles.map(function (u) { return esc(u.source) + ' : ' + esc(u.error); }).join('<br>') + '</div>';
}

const html = '<div style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#1d2430;max-width:640px;margin:0 auto">' +
  '<p style="font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:' + MUTED + ';margin:0">Reporting marketing hebdomadaire</p>' +
  '<h2 style="font-size:22px;margin:4px 0 2px">' + esc(cfg.site_name) + '</h2>' +
  '<p style="color:' + MUTED + ';margin:0 0 20px">Semaine du ' + day(a.current_start) + ' au ' + day(a.current_end) + ', comparée à la précédente</p>' +
  synth +
  '<table style="width:100%;border-collapse:collapse;font-size:14px;margin-top:22px"><tr style="color:' + MUTED + ';font-size:12px"><td style="padding:6px 12px"></td><td style="padding:6px 12px;text-align:right">Cette semaine</td><td style="padding:6px 12px;text-align:right">Précédente</td><td style="padding:6px 12px;text-align:right">Variation</td></tr>' + rows + '</table>' +
  queryTable('Requêtes qui gagnent des clics', s.gagnantes) +
  queryTable('Requêtes qui perdent des clics', s.perdantes) +
  missing +
  "<p style=\"font-size:12px;color:" + MUTED + ";margin-top:28px;line-height:1.5\">Search Console s'arrête quelques jours avant aujourd'hui : ses données arrivent avec 2 à 3 jours de retard. Comparaison des requêtes sur les 250 premières de chaque semaine.</p></div>";

const headline = parsed && parsed.titre ? clean(parsed.titre) : 'les chiffres de la semaine';
const subject = 'Reporting ' + cfg.site_name + ', semaine du ' + day(a.current_start) + ' : ' + (headline.length > 90 ? headline.slice(0, 87) + '...' : headline);

function orNull(ok, v) { return ok && v !== undefined ? v : null; }
const row = {
  run_id: a.run_id,
  period_start: DateTime.fromISO(a.current_start, { zone: 'Europe/Paris' }).toISO(),
  period_end: DateTime.fromISO(a.current_end, { zone: 'Europe/Paris' }).toISO(),
  sessions: orNull(g.status === 'ok', g.sessions),
  users: orNull(g.status === 'ok', g.users),
  key_events: orNull(g.status === 'ok', g.key_events),
  engagement_rate: orNull(g.status === 'ok', g.engagement_rate),
  sessions_change: orNull(g.status === 'ok', g.sessions_change),
  gsc_clicks: orNull(s.status === 'ok', s.clicks),
  gsc_impressions: orNull(s.status === 'ok', s.impressions),
  gsc_ctr: orNull(s.status === 'ok', s.ctr),
  gsc_position: orNull(s.status === 'ok', s.position),
  gsc_clicks_change: orNull(s.status === 'ok', s.clicks_change),
  ads_cost: orNull(ads.status === 'ok', ads.cost),
  ads_clicks: orNull(ads.status === 'ok', ads.interactions),
  top_queries: JSON.stringify((s.top_requetes || []).slice(0, 10)),
  summary: parsed ? clean(parsed.titre) + ' ' + (parsed.faits || []).map(clean).join(' ') : ''
};

return [{ json: { subject: subject, html: html, synthese_ok: !!parsed, row: row } }];
